// Reads one event of the source folder (subscribe object node).
// In: msg.payload = {eventType, path}. Out: msg.event = {kind, type, site,
// month}. Nothing is sent for a delete, another file type or another path.
var TYPES = [
  'plan_opt',
  'line_losses',
  'volume_loss_correction'
];
// Path: .../source/<type>/site=<Site>/<type>_<YYYY-MM>.csv
var PATTERN = /source\/([a-z_]+)\/site=([^\/]+)\/[a-z_]+_(\d{4}-\d{2})\.csv$/;

var event = msg.payload || {};
var path = String(event.path || msg.path || '');
var parts = PATTERN.exec(path);
if (event.eventType !== 'MODIFY' || !parts) {
  return null;
}
if (TYPES.indexOf(parts[1]) === -1) {
  return null;
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: parts[2] + ' ' + parts[3] + ' ' + parts[1]
});
return {
  topic: 'event',
  event: {
    kind: 'source',
    type: parts[1],
    site: parts[2],
    month: parts[3]
  }
};

// Reads one event of the reference folder (subscribe object node).
// In: msg.payload = {eventType, path}. Out: msg.event = {kind, type, site}.
// Nothing is sent for a delete, another file type or a folder we do not use.
var TYPES = [
  'machine_names',
  'shift_naming',
  'glidepaths',
  'equipment_coding'
];
// Path: .../reference/<type>/site=<Site>/<file>.csv
var PATTERN = /reference\/([a-z_]+)\/site=([^\/]+)\/[^\/]+\.csv$/i;

var event = msg.payload || {};
var path = String(event.path || msg.path || '');
var parts = PATTERN.exec(path);
if (event.eventType !== 'MODIFY' || !parts) {
  return null;
}
if (TYPES.indexOf(parts[1]) === -1) {
  return null;
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: parts[1] + ' ' + parts[2]
});
return {
  topic: 'event',
  event: {
    kind: 'reference',
    type: parts[1],
    site: parts[2]
  }
};

// Collects the file events in flow context "pending", one entry per target
// (source: site and month, reference: type and site). Nothing is sent on:
// the release node sends the jobs when the wait window of an entry is over.
// Set LISTENERS_ON to false to drop all events (for example a bulk upload).
var LISTENERS_ON = true;

if (!LISTENERS_ON) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'listeners OFF'
  });
  return null;
}

var event = msg.event;
var pending = flow.get('pending') || {};
var key = event.kind + '|' + event.site + '|';
key += event.kind === 'source' ? event.month : event.type;
var now = Date.now();

var entry = pending[key];
if (!entry) {
  entry = {
    kind: event.kind,
    site: event.site,
    month: event.month,
    type: event.kind === 'reference' ? event.type : null,
    types: {},
    first: now,
    events: 0
  };
}
entry.types[event.type] = true;
entry.events++;
pending[key] = entry;
flow.set('pending', pending);

node.status({
  fill: 'blue',
  shape: 'dot',
  text: Object.keys(pending).length + ' waiting'
});
return null;

// Runs on the clock. Takes the entries of flow context "pending" whose wait
// window is over and turns them into jobs {tables, sites, from, to}. The jobs
// go to global context "jobQueue" (the tab PBI report build takes them one by
// one). Out: one log line per job (for a debug node).
var SOURCE_WAIT_S = 120;
var REFERENCE_WAIT_S = 300;
// Months before the current month that a reference change rebuilds.
var REFERENCE_MONTHS_BACK = 3;
var MONTH_TABLES = [
  'pbi_plan_opt',
  'pbi_time_utilisation',
  'pbi_daily_losses'
];
var TABLES_OF = {
  plan_opt: MONTH_TABLES,
  line_losses: ['pbi_daily_losses'],
  volume_loss_correction: ['pbi_daily_losses'],
  machine_names: ['pbi_machine_names'],
  shift_naming: ['pbi_shift_naming'].concat(MONTH_TABLES),
  glidepaths: MONTH_TABLES,
  equipment_coding: ['pbi_daily_losses']
};

var pending = flow.get('pending') || {};
var now = Date.now();
var day = new Date(now).toISOString().slice(0, 10);
var queue = glob.get('jobQueue') || [];
var added = 0;
var logs = [];
var sourceGroups = {};

function monthIndex(text) {
  return Number(text.slice(0, 4)) * 12 + Number(text.slice(5, 7)) - 1;
}

function monthText(index) {
  var year = Math.floor(index / 12);
  var month = (index % 12) + 1;
  return year + '-' + (month < 10 ? '0' + month : month);
}

function addTables(list, tables) {
  tables.forEach(function (table) {
    if (list.indexOf(table) === -1) {
      list.push(table);
    }
  });
}

function addJob(job, why) {
  queue.push(job);
  added++;
  logs.push({
    topic: 'log',
    payload: day + ' [listener] JOB ' + why + ': ' + JSON.stringify(job)
  });
}

// Source files: one group per site and set of tables; the months of a group
// that follow each other become one job.
function groupSource(entry) {
  var tables = [];
  Object.keys(entry.types).forEach(function (type) {
    addTables(tables, TABLES_OF[type]);
  });
  var key = entry.site + '|' + tables.join(',');
  sourceGroups[key] = sourceGroups[key] || {
    site: entry.site,
    tables: tables,
    months: []
  };
  sourceGroups[key].months.push(monthIndex(entry.month));
}

function referenceJob(entry) {
  var tables = TABLES_OF[entry.type];
  var job = {
    tables: tables
  };
  if (entry.site !== 'All') {
    job.sites = [entry.site];
  }
  var hasMonths = tables.some(function (table) {
    return MONTH_TABLES.indexOf(table) !== -1;
  });
  if (hasMonths) {
    var current = monthIndex(new Date(now).toISOString().slice(0, 7));
    job.from = monthText(current - REFERENCE_MONTHS_BACK);
    job.to = monthText(current);
  }
  addJob(job, entry.type + ' ' + entry.site + ' changed');
}

Object.keys(pending).forEach(function (key) {
  var entry = pending[key];
  var wait = entry.kind === 'source' ? SOURCE_WAIT_S : REFERENCE_WAIT_S;
  if (now - entry.first < wait * 1000) {
    return;
  }
  delete pending[key];
  if (entry.kind === 'source') {
    groupSource(entry);
  } else {
    referenceJob(entry);
  }
});

Object.keys(sourceGroups).forEach(function (key) {
  var group = sourceGroups[key];
  var months = group.months.sort(function (a, b) {
    return a - b;
  });
  var start = months[0];
  var last = months[0];
  months.slice(1).concat([null]).forEach(function (index) {
    if (index === last + 1) {
      last = index;
      return;
    }
    if (index === last) {
      return;
    }
    addJob({
      tables: group.tables,
      sites: [group.site],
      from: monthText(start),
      to: monthText(last)
    }, group.site + ' source files changed');
    start = index;
    last = index;
  });
});

flow.set('pending', pending);
glob.set('jobQueue', queue);
var waiting = Object.keys(pending).length;
node.status({
  fill: added ? 'green' : 'blue',
  shape: 'dot',
  text: waiting + ' waiting, ' + added + ' job(s) queued'
});
return [logs];

// Runs on the clock. Reports "JOB DONE" once, when no log line came for
// QUIET_SECONDS. In: nothing (inject). Out: msg.payload = the text.
// The log lines are noted in global context by the tab PBI report build.
var QUIET_SECONDS = 30;
var last = glob.get('lastLog');
var done = glob.get('done');
if (!last || done) {
  return null;
}

var quiet = (Date.now() - last) / 1000;
if (quiet < QUIET_SECONDS) {
  return null;
}
glob.set('done', true);
node.status({
  fill: 'green',
  shape: 'dot',
  text: 'quiet since ' + new Date(last).toISOString().slice(11, 19)
});
return {
  payload: 'JOB DONE: no log line for ' + Math.round(quiet) + ' s'
};
